package main

import (
	"bufio"
	"fmt"
	"os"
)

func divisors(num int64) []int64 {
	var ret []int64
	var i int64
	for i = 2; i*i < num; i++ {
		if num%i == 0 {
			ret = append(ret, i)
			ret = append(ret, num/i)
		}
	}
	if i*i == num {
		ret = append(ret, i)
	}
	return ret
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n, m, k int64
	for {
		_, err := fmt.Fscan(in, &n, &m, &k)
		if err != nil {
			break
		}

		if n%2 == 0 {
			fmt.Fprintln(out, "Marsel")
			continue
		}

		div := divisors(m)
		if m > 1 {
			div = append(div, 1)
		}

		flag := false
		for _, d := range div {
			if d >= k {
				flag = true
				break
			}
		}

		if flag {
			fmt.Fprintln(out, "Timur")
		} else {
			fmt.Fprintln(out, "Marsel")
		}
	}
}

